 export function latestAsOf(events, queries) {
+  const sorted = [...events].sort((a, b) => a.at - b.at);
+  return queries.map((q) => {
+    let hit = null;
+    for (const e of sorted) { if (e.at <= q.at) hit = e; else break; }
+    return hit;
+  });
 }

